    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We generate a strictly increasing integer weight sequence via a quadratic template
# w_k = A*k^2 + B*k + C, with A>=1, B>=0, C>=0 to ensure monotone increase.
# We also ensure the resulting valid n-set is neither trivial nor full to enforce difficulty.
for _ in range(200):
  alpha = rng.randint(6, 10)
  A = rng.choice([1, 1, 1, 2])  # bias toward 1 for varied thresholds
  B = rng.randint(0, 2)
  C = rng.randint(0, 2)
  weights = [A*(k*k) + B*k + C for k in range(1, alpha+1)]
  # Sanity: strictly increasing and positive
  if any(weights[i] <= weights[i-1] for i in range(1, alpha)):
    continue
  if any(w <= 0 for w in weights):
    continue
  # Compute the valid n-set by the derived necessary & sufficient condition: sum_{k=1}^{n-1} w_k <= w_n
  prefix_sums = [0]
  s = 0
  for w in weights:
    s += w
    prefix_sums.append(s)
  valid = []
  for n in range(1, alpha+1):
    lhs = prefix_sums[n-1]  # sum of first n-1 weights
    rhs = weights[n-1]      # w_n
    if lhs <= rhs:
      valid.append(n)
  # Enforce non-triviality: at least 2 valid, but not all
  if 2 <= len(valid) <= alpha-1:
    return {'alpha': alpha, 'weights': weights}
# Fallback deterministic choice if random attempts failed (rare)
alpha = 6
A, B, C = 1, 0, 0
weights = [A*(k*k) + B*k + C for k in range(1, alpha+1)]
return {'alpha': alpha, 'weights': weights}

